<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use Illuminate\Http\Request;
class AddressController extends Controller { public function index(Request $r){return $r->user()->addresses()->latest()->get();} public function store(Request $r){$d=$r->validate(['label'=>'required','recipient_name'=>'required','phone'=>'required','line1'=>'required','line2'=>'nullable','city'=>'required','province'=>'nullable','postal_code'=>'nullable','latitude'=>'nullable|numeric','longitude'=>'nullable|numeric','is_default'=>'boolean']); if(($d['is_default']??false))$r->user()->addresses()->update(['is_default'=>false]); return $r->user()->addresses()->create($d);} public function update(Request $r,$id){$a=$r->user()->addresses()->findOrFail($id); $d=$r->validate(['label'=>'required','recipient_name'=>'required','phone'=>'required','line1'=>'required','line2'=>'nullable','city'=>'required','province'=>'nullable','postal_code'=>'nullable','latitude'=>'nullable|numeric','longitude'=>'nullable|numeric','is_default'=>'boolean']); if(($d['is_default']??false))$r->user()->addresses()->update(['is_default'=>false]); $a->update($d); return $a;} public function destroy(Request $r,$id){$r->user()->addresses()->findOrFail($id)->delete(); return ['message'=>'Deleted'];}}